            artifact.metadata["call_statements"] = [c for c, _ in result.call_statements]
            artifact.metadata["local_declarations"] = [
                {"name": f.name, "pic": f.pic, "byte_size": f.byte_size, "line": f.line}
                for f in result.local_declarations
            ]
            artifact.metadata["file_selects"] = [
                {"logical": s.logical_name, "assign_to": s.assign_to}
                for s in result.file_selects
            ]

        elif artifact_type == ArtifactType.COPYBOOK:
            result = parse_copybook_file(path)
            self._copybook_results[artifact.id] = result
            cpy_name = _normalise_copybook_name(path.name)
            self._copybook_by_name[cpy_name] = artifact.id
            artifact.metadata["fields"] = [
                {"name": f.name, "pic": f.pic, "byte_size": f.byte_size, "level": f.level}
                for f in result.fields if f.pic
            ]
            artifact.metadata["copy_statements"] = [c for c, _ in result.copy_statements]

        elif artifact_type == ArtifactType.HLASM:
            result = parse_hlasm_file(path)
            self._hlasm_results[artifact.id] = result
            artifact.metadata["sections"] = [
                {
                    "name": s.name,
                    "kind": s.kind,
                    "fields": [
                        {"label": f.label, "opcode": f.opcode, "operand": f.operand,
