            # AFP is isolated — just record it exists
            artifact.metadata["afp"] = True

    # ------------------------------------------------------------------
    # Edge derivation
    # ------------------------------------------------------------------

    def _resolve_artifact_id(self, name: str) -> Optional[str]:
        """Try to find an artifact id by name (stem, copybook name, etc.)."""
        upper = name.upper()
