"""Graph builder.

Builds a NetworkX directed graph from a DependencyGraph model, preserving
DependencyKind edge attributes and SourceLocation information.
"""

from __future__ import annotations

from typing import Any

import networkx as nx

from zforge.models import (
    Artifact,
    ArtifactType,
    DependencyGraph,
    DependencyKind,
)


def build_nx_graph(dep_graph: DependencyGraph) -> nx.DiGraph:
    """Build a NetworkX DiGraph from a DependencyGraph model.

    Nodes carry the full Artifact as a ``artifact`` attribute.
    Edges carry ``kind`` (DependencyKind) and ``line`` attributes.
    """
